from sentence_transformers import SentenceTransformer
import numpy as np

model = SentenceTransformer("all-MiniLM-L6-v2")

def dedupe(chunks: list[str], thresh: float = {{threshold}}) -> list[str]:
    if not chunks:
        return []
    vecs = model.encode(chunks, normalize_embeddings=True)
    keep, kept = [], []
    for i, v in enumerate(vecs):
        if not kept or max((v @ np.array(kept).T).flatten()) < thresh:
            kept.append(v); keep.append(chunks[i])
    return keep
